import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

// Load config from mounted volume
const dbConfig = JSON.parse(readFileSync('/etc/app/db-config.json', 'utf8'));

const pool = new Pool({
  host: dbConfig.host,
  port: dbConfig.port,
  database: dbConfig.database,
  user: dbConfig.user,
  password: dbConfig.password,
  ssl: { rejectUnauthorized: true, ca: readFileSync('/etc/app/rds-ca.pem') }
});

// Middleware: verify internal service token
function verifyServiceToken(req, res, next) {
  const token = req.headers['x-service-token'];
  if (!token) return res.status(401).json({ error: 'Missing service token' });
  // HMAC verification against shared secret
  const [payload, sig] = token.split('.');
  const expected = crypto.createHmac('sha256', process.env.SERVICE_SECRET || 'dev-secret')
    .update(payload).digest('hex');
  if (sig !== expected) return res.status(403).json({ error: 'Invalid token' });
  req.servicePayload = JSON.parse(Buffer.from(payload, 'base64').toString());
  next();
}

// Template rendering endpoint - accepts report template with user-controlled format
app.post('/api/v2/reports/generate', verifyServiceToken, async (req, res) => {
  try {
    const { templateId, filters, outputFormat } = req.body;

    if (!templateId || !filters) {
      return res.status(400).json({ error: 'templateId and filters required' });
    }

    // Fetch template definition
    const templateResult = await pool.query(
      'SELECT * FROM report_templates WHERE id = $1 AND org_id = $2',
      [templateId, req.servicePayload.org_id]
    );

    if (templateResult.rows.length === 0) {
      return res.status(404).json({ error: 'Template not found' });
    }

    const template = templateResult.rows[0];

    // Build dynamic query from template and user filters
    // The template.base_query is trusted (from DB), but filters are user-controlled
    let query = template.base_query; // e.g., "SELECT * FROM transactions WHERE org_id = $1"
    let params = [req.servicePayload.org_id];
    let paramIdx = 2;

    // VULNERABILITY: filter values are interpolated without parameterization
    if (filters.date_range) {
      query += ` AND created_at BETWEEN '${filters.date_range.start}' AND '${filters.date_range.end}'`;
    }
    if (filters.status) {
      query += ` AND status = '${filters.status}'`;
    }
    if (filters.amount_gt) {
      query += ` AND amount > ${filters.amount_gt}`;
    }
    if (filters.category) {
      query += ` AND category IN (${filters.category.map(c => `'${c}'`).join(',')})`;
    }

    // Execute the constructed query
    const result = await pool.query(query, params);

    // Format output
    const report = {
      generated_at: new Date().toISOString(),
      template_name: template.name,
      record_count: result.rows.length,
      data: result.rows
    };

    res.json(report);
  } catch (err) {
    console.error('Report generation error:', err.message);
    res.status(500).json({ error: 'Internal error generating report' });
  }
});

// Health check
app.get('/healthz', (req, res) => res.json({ status: 'ok' }));

app.listen(8080, '0.0.0.0', () => {
  console.log('Report service listening on :8080');
});
